export const CONTRACT_VERSION = "2026-08-13";
export const MAX_TASK_TEXT_LENGTH = 8000;
export const MAX_READ_LINES = 200;
export const MAX_TIMEOUT_MS = 900000;
export const MAX_RESULT_SUMMARY_LENGTH = 2000;
export const JOB_TYPES = ["implementation", "review", "dataverse-authorized-test"];
export const RUNNERS = ["devon", "greg"];
export const JOB_STATES = ["draft", "approved", "creating", "ready", "working", "unknown", "handoff_ready", "closed", "refused", "failed"];
export const BROKER_VERBS = ["create_job", "prompt_job", "job_status", "read_job", "handoff_job", "close_job", "recover_job"];
const RESULT_CATEGORIES = ["ok", "refused", "busy", "timeout", "unknown", "failed"];
const record = (value) => { if (typeof value !== "object" || value === null || Array.isArray(value)) throw new Error("Input must be an object"); return value; };
const exact = (value, allowed) => { const extra = Object.keys(value).filter((key) => !allowed.includes(key)); if (extra.length) throw new Error(`Unsupported field(s): ${extra.join(", ")}`); };
const logical = (name, value) => { if (typeof value !== "string" || !/^[a-z0-9][a-z0-9_-]{0,63}$/.test(value)) throw new Error(`${name} must be a logical key`); return value; };
const jobId = (value) => { if (typeof value !== "string" || !/^[a-zA-Z0-9_-]{8,80}$/.test(value)) throw new Error("jobId must be opaque"); return value; };
const taskText = (value) => { if (typeof value !== "string" || !value.trim() || value.length > MAX_TASK_TEXT_LENGTH) throw new Error(`taskText must contain 1-${MAX_TASK_TEXT_LENGTH} characters`); return value; };
export const parseJobRequest = (input) => { const value = record(input); exact(value, ["contractVersion", "jobType", "runner", "project", "taskText"]); if (value.contractVersion !== CONTRACT_VERSION) throw new Error("Unsupported contract version"); if (!JOB_TYPES.includes(value.jobType)) throw new Error("Unsupported jobType"); if (!RUNNERS.includes(value.runner)) throw new Error("Unsupported runner"); return { contractVersion: CONTRACT_VERSION, jobType: value.jobType, runner: value.runner, project: logical("project", value.project), taskText: taskText(value.taskText) }; };
export const parseBrokerCommand = (input) => { const value = record(input); if (value.contractVersion !== CONTRACT_VERSION) throw new Error("Unsupported contract version"); if (!BROKER_VERBS.includes(value.verb)) throw new Error("Unsupported broker verb"); const common = { contractVersion: CONTRACT_VERSION, jobId: jobId(value.jobId) }; if (value.verb === "create_job") { exact(value, ["contractVersion", "verb", "jobId", "project", "profile", "label"]); return { ...common, verb: "create_job", project: logical("project", value.project), profile: logical("profile", value.profile), label: logical("label", value.label) }; } if (value.verb === "prompt_job") { exact(value, ["contractVersion", "verb", "jobId", "taskText", "timeoutMs"]); if (!Number.isInteger(value.timeoutMs) || Number(value.timeoutMs) < 1000 || Number(value.timeoutMs) > MAX_TIMEOUT_MS) throw new Error("timeoutMs is out of range"); return { ...common, verb: "prompt_job", taskText: taskText(value.taskText), timeoutMs: Number(value.timeoutMs) }; } if (value.verb === "read_job") { exact(value, ["contractVersion", "verb", "jobId", "maxLines"]); if (!Number.isInteger(value.maxLines) || Number(value.maxLines) < 1 || Number(value.maxLines) > MAX_READ_LINES) throw new Error("maxLines is out of range"); return { ...common, verb: "read_job", maxLines: Number(value.maxLines) }; } exact(value, ["contractVersion", "verb", "jobId"]); return { ...common, verb: value.verb }; };
export const parseBrokerResult = (input) => { const value = record(input); exact(value, ["contractVersion", "jobId", "state", "category", "branch", "commitSha", "prUrl", "summary"]); if (value.contractVersion !== CONTRACT_VERSION) throw new Error("Unsupported contract version"); const id = jobId(value.jobId); if (!JOB_STATES.includes(value.state)) throw new Error("Unsupported job state"); if (!RESULT_CATEGORIES.includes(value.category)) throw new Error("Unsupported result category"); const result = { contractVersion: CONTRACT_VERSION, jobId: id, state: value.state, category: value.category }; if (value.branch !== undefined) { if (typeof value.branch !== "string" || !/^jobs\/[a-z0-9_-]{8,80}$/.test(value.branch)) throw new Error("Invalid job branch"); result.branch = value.branch; } if (value.commitSha !== undefined) { if (typeof value.commitSha !== "string" || !/^[a-f0-9]{40}$/.test(value.commitSha)) throw new Error("Invalid commit SHA"); result.commitSha = value.commitSha; } if (value.prUrl !== undefined) { if (typeof value.prUrl !== "string" || !/^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/pull\/[1-9]\d{0,9}$/.test(value.prUrl)) throw new Error("Invalid GitHub PR URL"); result.prUrl = value.prUrl; } if (value.summary !== undefined) { if (typeof value.summary !== "string" || value.summary.length > MAX_RESULT_SUMMARY_LENGTH) throw new Error("Result summary is too large"); result.summary = value.summary; } return result; };
